  "track.sysdesign.m.upload.s.resumable.s3.title": "Có mạng lại: HEAD /uploads/abc → Upload-Offset: 190 MB",
  "track.sysdesign.m.upload.s.resumable.s3.explain": "Server, không phải app, nói đã nhận tới đâu.",
  "track.sysdesign.m.upload.ev.resumable.s3": "Có mạng lại: HEAD /uploads/abc → Upload-Offset: 190 MB",
